import{_ as o,C as a,o as s,c as r,ag as n,E as i}from"./chunks/framework.CtWPcAmt.js";const m=JSON.parse('{"title":"Manage Inventory","description":"","frontmatter":{},"headers":[],"relativePath":"inventory/manage-inventory.md","filePath":"inventory/manage-inventory.md","lastUpdated":1786088921000}'),l={name:"inventory/manage-inventory.md"};function c(g,t,u,d,p,h){const e=a("ImagePopup");return s(),r("div",null,[t[0]||(t[0]=n('<h1 id="manage-inventory" tabindex="-1">Manage Inventory <a class="header-anchor" href="#manage-inventory" aria-label="Permalink to &quot;Manage Inventory&quot;">​</a></h1><p>Manage Inventory is the seller&#39;s stock control room — one screen to see and edit quantities for every product across every inventory source, with bulk tools for updating many products at once.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What the manage-inventory screen shows</li><li>How to edit stock per source</li><li>How to bulk-adjust stock and listing status</li></ul></div><h2 id="the-inventory-screen" tabindex="-1">The inventory screen <a class="header-anchor" href="#the-inventory-screen" aria-label="Permalink to &quot;The inventory screen&quot;">​</a></h2><p>Open <strong>Inventories → Manage Inventory</strong>. Each row is a stock-carrying product (simple and virtual products; configurable variants appear as their own rows), showing its image, name, SKU, type, <strong>listing status</strong>, <strong>sales</strong> (sold / undelivered / cancelled), and total <strong>stock</strong>.</p>',5)),i(e,{src:"/images/manage-inventory/manage.png",alt:"Manage Inventory screen"}),t[1]||(t[1]=n('<p>You can <strong>search</strong>, <strong>filter</strong> (by listing status, category, type, approval), and jump straight to a product&#39;s pricing with the <strong>Edit price</strong> link on each row.</p><h2 id="editing-stock" tabindex="-1">Editing stock <a class="header-anchor" href="#editing-stock" aria-label="Permalink to &quot;Editing stock&quot;">​</a></h2><ul><li><strong>Per source</strong> — expand a product row to reveal a quantity input for each of your <a href="/inventory/inventory-source-management">inventory sources</a>; type the new quantities. A product with <strong>stock not managed</strong> is always available and shows no quantity.</li><li><strong>Bulk stock tool</strong> — select several products, then choose a <strong>source</strong> (all sources or a specific one), an <strong>action</strong> (<strong>set</strong>, <strong>add</strong>, or <strong>remove</strong>), and a <strong>value</strong>, and <strong>Apply</strong> it across the selection.</li><li><strong>Save</strong> — a bar at the bottom tracks unsaved changes; <strong>Save Inventories</strong> writes them all at once (or <strong>Discard</strong> to revert).</li></ul><h2 id="bulk-listing-status" tabindex="-1">Bulk listing status <a class="header-anchor" href="#bulk-listing-status" aria-label="Permalink to &quot;Bulk listing status&quot;">​</a></h2><p>Select products and use the <strong>Update Status</strong> action to switch their listing status to <strong>Active</strong> or <strong>Inactive</strong> in one move — handy for taking a range of products on or off the storefront quickly.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the bulk stock tool with <strong>set</strong> after a stock-take, and <strong>add</strong> / <strong>remove</strong> when receiving or shipping batches — it&#39;s far faster than editing rows one by one.</p></div>',6))])}const y=o(l,[["render",c]]);export{m as __pageData,y as default};
